import React from 'react';

const Generator = () => {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold text-gray-900">Product Description Generator</h1>
      <p className="text-gray-600 mt-2">Generate AI-powered product descriptions</p>
    </div>
  );
};

export default Generator;
